COPY public.faqs (id, question, answer, sort_order, status, created_at, updated_at, deleted_at) FROM stdin;
1	TechStore có bán sản phẩm chính hãng không?	Có. TechStore chỉ kinh doanh các sản phẩm có nguồn gốc rõ ràng, đầy đủ thông tin thương hiệu, cấu hình và chính sách bảo hành. Với các sản phẩm laptop, màn hình, linh kiện và phụ kiện, khách hàng sẽ được tư vấn kỹ trước khi mua.	1	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
2	Thời gian bảo hành sản phẩm là bao lâu?	Thời gian bảo hành tùy thuộc vào từng sản phẩm và chính sách của nhà sản xuất. Thông thường laptop, màn hình và linh kiện có thời gian bảo hành từ 12 đến 36 tháng. Thông tin bảo hành cụ thể sẽ được hiển thị trong chi tiết sản phẩm hoặc hóa đơn mua hàng.	2	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
3	TechStore có hỗ trợ giao hàng toàn quốc không?	Có. TechStore hỗ trợ giao hàng toàn quốc. Phí vận chuyển và thời gian giao hàng sẽ phụ thuộc vào địa chỉ nhận hàng, kích thước sản phẩm và đơn vị vận chuyển.	3	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
4	Tôi có thể kiểm tra trạng thái đơn hàng ở đâu?	Sau khi đăng nhập, khách hàng có thể vào mục Tài khoản của tôi, chọn Đơn hàng của tôi để xem trạng thái đơn hàng. Các trạng thái bao gồm chờ xác nhận, đã xác nhận, đang giao hàng, hoàn thành hoặc đã hủy.	4	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
5	TechStore có hỗ trợ thanh toán khi nhận hàng không?	Có. Khách hàng có thể chọn phương thức thanh toán khi nhận hàng nếu đơn hàng đủ điều kiện hỗ trợ COD. Ngoài ra, hệ thống có thể mở rộng thêm các phương thức thanh toán trực tuyến trong tương lai.	5	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
6	Tôi có thể sử dụng mã giảm giá như thế nào?	Tại bước thanh toán, khách hàng nhập mã giảm giá vào ô áp mã. Nếu mã còn hiệu lực, đơn hàng đủ điều kiện giá trị tối thiểu và chưa vượt quá lượt sử dụng, hệ thống sẽ tự động tính số tiền được giảm.	6	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
7	Mỗi đơn hàng có thể dùng nhiều mã giảm giá không?	Hiện tại mỗi đơn hàng chỉ được áp dụng một mã giảm giá. Khách hàng nên chọn mã phù hợp nhất với giá trị đơn hàng để nhận ưu đãi tốt nhất.	7	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
8	Tôi có thể đổi trả sản phẩm sau khi mua không?	Khách hàng có thể yêu cầu đổi trả nếu sản phẩm gặp lỗi kỹ thuật, giao sai mẫu, sai cấu hình hoặc không đúng mô tả. Sản phẩm cần còn đầy đủ phụ kiện, hộp, hóa đơn và không bị hư hỏng do người dùng.	8	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
9	TechStore có hỗ trợ build PC theo nhu cầu không?	Có. TechStore hỗ trợ tư vấn build PC theo nhu cầu học tập, làm việc, thiết kế đồ họa, dựng video, livestream hoặc chơi game. Khách hàng có thể liên hệ để được tư vấn cấu hình phù hợp với ngân sách.	9	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
10	Tôi có thể yêu cầu xuất hóa đơn không?	Có. Nếu khách hàng cần xuất hóa đơn, vui lòng cung cấp đầy đủ thông tin trong quá trình đặt hàng hoặc liên hệ bộ phận hỗ trợ sau khi đặt hàng thành công.	10	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
11	Sản phẩm hết hàng thì khi nào có lại?	Thời gian nhập lại hàng tùy thuộc vào nhà cung cấp và từng dòng sản phẩm. Khách hàng có thể theo dõi website hoặc liên hệ TechStore để được tư vấn sản phẩm thay thế phù hợp.	11	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
12	Tôi có thể hủy đơn hàng sau khi đặt không?	Khách hàng có thể yêu cầu hủy đơn khi đơn hàng chưa được giao cho đơn vị vận chuyển. Nếu đơn hàng đã chuyển sang trạng thái đang giao hàng, việc hủy đơn sẽ phụ thuộc vào tình trạng vận chuyển thực tế.	12	ACTIVE	2026-05-23 01:43:44.845811	2026-05-23 01:43:44.845811	\N
